files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --accent: #ff6b6b;
  --accent-hover: #ff4757;
  --secondary: #4a4a6a;
  --secondary-hover: #5a5a7a;
  --border: #3a3a5a;
  --focus: #ffd93d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 4px;
  text-align: center;
}

.subtitle {
  text-align: center;
  color: #a0a0c0;
  margin-bottom: 24px;
  font-size: 0.95rem;
}

.input-group {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}

input[type="number"] {
  flex: 1;
  padding: 12px 16px;
  border-radius: 10px;
  border: 2px solid var(--border);
  background: #1e1e2f;
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
  min-width: 0;
}

input[type="number"]:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 217, 61, 0.25);
}

input[type="number"]::placeholder {
  color: #6a6a8a;
}

.btn {
  padding: 12px 20px;
  border-radius: 10px;
  border: none;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.btn.secondary {
  background: var(--secondary);
  color: var(--text);
  width: 100%;
  margin-top: 16px;
}

.btn.secondary:hover {
  background: var(--secondary-hover);
}

.stats {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.stat {
  flex: 1;
  background: #1e1e2f;
  border-radius: 10px;
  padding: 12px 8px;
  text-align: center;
  border: 1px solid var(--border);
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #a0a0c0;
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

.readings {
  list-style: none;
  max-height: 200px;
  overflow-y: auto;
  margin-bottom: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.readings li {
  background: #1e1e2f;
  padding: 10px 14px;
  border-radius: 8px;
  border: 1px solid var(--border);
  font-size: 0.95rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.readings li .value {
  font-weight: 600;
  color: var(--accent);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .input-group {
    flex-direction: column;
  }
  .btn.primary {
    width: 100%;
  }
}

(function () {
  'use strict';

  var readings = [];
  var form = document.getElementById('temp-form');
  var input = document.getElementById('temp-input');
  var list = document.getElementById('readings-list');
  var minEl = document.getElementById('min-val');
  var maxEl = document.getElementById('max-val');
  var avgEl = document.getElementById('avg-val');
  var clearBtn = document.getElementById('clear-btn');

  function updateStats() {
    if (readings.length === 0) {
      minEl.textContent = '—';
      maxEl.textContent = '—';
      avgEl.textContent = '—';
      return;
    }
    var min = Math.min.apply(null, readings);
    var max = Math.max.apply(null, readings);
    var sum = readings.reduce(function (a, b) { return a + b; }, 0);
    var avg = sum / readings.length;
    minEl.textContent = min.toFixed(1) + '°C';
    maxEl.textContent = max.toFixed(1) + '°C';
    avgEl.textContent = avg.toFixed(1) + '°C';
  }

  function renderList() {
    list.innerHTML = '';
    readings.forEach(function (val) {
      var li = document.createElement('li');
      var span = document.createElement('span');
      span.className = 'value';
      span.textContent = val.toFixed(1) + '°C';
      li.appendChild(span);
      list.appendChild(li);
    });
  }

  function addReading(value) {
    readings.push(value);
    renderList();
    updateStats();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var raw = input.value.trim();
    if (raw === '') return;
    var num = parseFloat(raw);
    if (isNaN(num)) {
      input.setCustomValidity('Please enter a valid number.');
      input.reportValidity();
      return;
    }
    input.setCustomValidity('');
    addReading(num);
    input.value = '';
    input.focus();
  });

  clearBtn.addEventListener('click', function () {
    readings = [];
    renderList();
    updateStats();
    input.focus();
  });

  // Initialize
  updateStats();
})();
